1	//! Generic CLI Introspection Adapter
2	//!
3	//! Generalizes the gcloud introspection pattern into a reusable framework
4	//! for ANY CLI program (incus, docker, kubectl, helm, etc.).
5	//!
6	//! Handles both Go/cobra-style and Python/click-style help output formats,
7	//! as well as gcloud's ALL-CAPS section headers.
8	//!
9	//! # Usage
10	//!
11	//! ```rust,no_run
12	//! use op_inspector::cli::{CliParser, introspect_cli};
13	//!
14	//! // Quick introspection
15	//! let schema = introspect_cli("incus", 3).await?;
16	//!
17	//! // Custom help flag (e.g., for programs that use "-h" only)
18	//! let parser = CliParser::with_help_flag("mytool", "-h");
19	//! let schema = parser.introspect_full(2).await?;
20	//! ```
21	
22	use anyhow::{Context, Result};
23	use regex::Regex;
24	use serde::{Deserialize, Serialize};
25	use std::collections::HashMap;
26	use std::sync::Arc;
27	use tokio::sync::Mutex;
28	use tracing::{debug, info, warn};
29	
30	// ---------------------------------------------------------------------------
31	// Data structures
32	// ---------------------------------------------------------------------------
33	
34	/// Root schema for a CLI program's command hierarchy.
35	#[derive(Debug, Clone, Serialize, Deserialize)]
36	pub struct CliSchema {
37	    /// The program name (e.g., "incus", "docker", "kubectl")
38	    pub program: String,
39	    /// Version string as reported by the program
40	    pub version: String,
41	    /// Root command hierarchy
42	    pub hierarchy: CliCommand,
43	    /// Introspection statistics
44	    pub statistics: CliStats,
45	}
46	
47	/// A command or command group within the CLI hierarchy (recursive).
48	#[derive(Debug, Clone, Serialize, Deserialize)]
49	pub struct CliCommand {
50	    /// Command name (e.g., "list", "config", "admin")
51	    pub name: String,
52	    /// Full command path (e.g., "incus config edit")
53	    pub full_path: String,
54	    /// Human-readable description
55	    pub description: String,
56	    /// Whether this node is a group (has subcommands)
57	    pub is_group: bool,
58	    /// Available flags / options
59	    pub flags: Vec<CliFlag>,
60	    /// Positional arguments
61	    pub positional_args: Vec<CliArg>,
62	    /// Subcommands keyed by name
63	    pub subcommands: HashMap<String, CliCommand>,
64	}
65	
66	impl Default for CliCommand {
67	    fn default() -> Self {
68	        Self {
69	            name: "root".to_string(),
70	            full_path: String::new(),
71	            description: String::new(),
72	            is_group: true,
73	            flags: vec![],
74	            positional_args: vec![],
75	            subcommands: HashMap::new(),
76	        }
77	    }
78	}
79	
80	/// A CLI flag / option.
81	#[derive(Debug, Clone, Serialize, Deserialize)]
82	pub struct CliFlag {
83	    /// Long flag name including dashes (e.g., "--format")
84	    pub name: String,
85	    /// Optional short flag (e.g., "-f")
86	    pub short_name: Option<String>,
87	    /// Description text
88	    pub description: String,
89	    /// Whether the flag is required
90	    pub required: bool,
91	    /// Inferred value type ("string", "integer", "boolean")
92	    pub value_type: String,
93	    /// Default value if any
94	    pub default: Option<String>,
95	    /// Allowed choices if any
96	    pub choices: Vec<String>,
97	}
98	
99	/// A positional argument.
100	#[derive(Debug, Clone, Serialize, Deserialize)]
101	pub struct CliArg {
102	    /// Argument name
103	    pub name: String,
104	    /// Description text
105	    pub description: String,
106	    /// Whether the argument is required
107	    pub required: bool,
108	}
109	
110	/// Statistics gathered during introspection.
111	#[derive(Debug, Clone, Serialize, Deserialize)]
112	pub struct CliStats {
113	    pub total_groups: usize,
114	    pub total_commands: usize,
115	    pub total_flags: usize,
116	    pub introspection_time_ms: u128,
117	}
118	
119	impl Default for CliStats {
120	    fn default() -> Self {
121	        Self {
122	            total_groups: 0,
123	            total_commands: 0,
124	            total_flags: 0,
125	            introspection_time_ms: 0,
126	        }
127	    }
128	}
129	
130	// ---------------------------------------------------------------------------
131	// CliParser
132	// ---------------------------------------------------------------------------
133	
134	/// Generic CLI introspection parser.
135	///
136	/// Runs a program's help output, parses it to discover command groups,
137	/// subcommands, flags, and arguments, then builds a [`CliSchema`].
138	pub struct CliParser {
139	    /// The program binary name (e.g., "incus")
140	    program: String,
141	    /// In-memory cache of help text keyed by command path
142	    cache: Arc<Mutex<HashMap<String, String>>>,
143	    /// The flag used to request help (usually "--help")
144	    help_flag: String,
145	}
146	
147	impl CliParser {
148	    /// Create a new parser for the given program with the default `--help` flag.
149	    pub fn new(program: &str) -> Self {
150	        Self {
151	            program: program.to_string(),
152	            cache: Arc::new(Mutex::new(HashMap::new())),
153	            help_flag: "--help".to_string(),
154	        }
155	    }
156	
157	    /// Create a new parser with a custom help flag (e.g., "-h").
158	    pub fn with_help_flag(program: &str, help_flag: &str) -> Self {
159	        Self {
160	            program: program.to_string(),
161	            cache: Arc::new(Mutex::new(HashMap::new())),
162	            help_flag: help_flag.to_string(),
163	        }
164	    }
165	
166	    /// Attempt to retrieve the program version.
167	    ///
168	    /// Tries `program --version` first; if that fails or returns empty output
169	    /// it falls back to `program version`. Returns the first non-empty line.
170	    pub async fn get_version(&self) -> Result<String> {
171	        // Try --version first (most common)
172	        let output = tokio::process::Command::new(&self.program)
173	            .arg("--version")
174	            .output()
175	            .await
176	            .context(format!("Failed to run {} --version", self.program))?;
177	
178	        let stdout = String::from_utf8_lossy(&output.stdout);
179	        if let Some(first_line) = stdout.lines().find(|l| !l.trim().is_empty()) {
180	            return Ok(first_line.trim().to_string());
181	        }
182	
183	        // Fallback: some programs use a "version" subcommand (e.g., docker)
184	        let output = tokio::process::Command::new(&self.program)
185	            .arg("version")
186	            .output()
187	            .await
188	            .context(format!("Failed to run {} version", self.program))?;
189	
190	        let stdout = String::from_utf8_lossy(&output.stdout);
191	        let first_line = stdout
192	            .lines()
193	            .find(|l| !l.trim().is_empty())
194	            .unwrap_or("unknown");
195	        Ok(first_line.trim().to_string())
196	    }
197	
198	    /// Run the help command for a given command path and cache the result.
199	    ///
200	    /// Executes: `program [path...] <help_flag>`
201	    /// Both stdout and stderr are captured and concatenated.
202	    async fn run_help(&self, command_path: &[String]) -> Result<String> {
203	        let cache_key = if command_path.is_empty() {
204	            "_root".to_string()
205	        } else {
206	            command_path.join(".")
207	        };
208	
209	        // Check cache first
210	        {
211	            let cache = self.cache.lock().await;
212	            if let Some(cached) = cache.get(&cache_key) {
213	                return Ok(cached.clone());
214	            }
215	        }
216	
217	        let mut cmd = tokio::process::Command::new(&self.program);
218	        for part in command_path {
219	            cmd.arg(part);
220	        }
221	        cmd.arg(&self.help_flag);
222	
223	        debug!(
224	            "Running: {} {} {}",
225	            self.program,
226	            command_path.join(" "),
227	            self.help_flag
228	        );
229	
230	        let output = cmd.output().await.context(format!(
231	            "Failed to run {} {} {}",
232	            self.program,
233	            command_path.join(" "),
234	            self.help_flag
235	        ))?;
236	
237	        // Combine stdout and stderr — many CLIs print help to stderr
238	        let help_text = String::from_utf8_lossy(&output.stdout).to_string()
239	            + &String::from_utf8_lossy(&output.stderr);
240	
241	        // Cache the result
242	        {
243	            let mut cache = self.cache.lock().await;
244	            cache.insert(cache_key, help_text.clone());
245	        }
246	
247	        Ok(help_text)
248	    }
249	
250	    /// Full introspection entry point.
251	    ///
252	    /// Recursively discovers the entire command hierarchy up to `max_depth`.
253	    pub async fn introspect_full(&self, max_depth: usize) -> Result<CliSchema> {
254	        let start = std::time::Instant::now();
255	
256	        info!(
257	            "Starting CLI introspection for '{}' (max_depth={})",
258	            self.program, max_depth
259	        );
260	
261	        let version = self
262	            .get_version()
263	            .await
264	            .unwrap_or_else(|_| "unknown".to_string());
265	
266	        info!("{} version: {}", self.program, version);
267	
268	        let mut stats = CliStats::default();
269	        let hierarchy = self
270	            .introspect_command_inner(&[], 0, max_depth, &mut stats)
271	            .await?;
272	
273	        stats.introspection_time_ms = start.elapsed().as_millis();
274	
275	        info!(
276	            "Introspection complete for '{}': {} groups, {} commands, {} flags in {}ms",
277	            self.program,
278	            stats.total_groups,
279	            stats.total_commands,
280	            stats.total_flags,
281	            stats.introspection_time_ms
282	        );
283	
284	        Ok(CliSchema {
285	            program: self.program.clone(),
286	            version,
287	            hierarchy,
288	            statistics: stats,
289	        })
290	    }
291	
292	    /// Recursively introspect a single command node.
293	    ///
294	    /// Uses `Box::pin` to allow async recursion through the subcommand tree.
295	    async fn introspect_command_inner(
296	        &self,
297	        command_path: &[String],
298	        depth: usize,
299	        max_depth: usize,
300	        stats: &mut CliStats,
301	    ) -> Result<CliCommand> {
302	        if depth > max_depth {
303	            return Ok(CliCommand::default());
304	        }
305	
306	        let full_path = if command_path.is_empty() {
307	            self.program.clone()
308	        } else {
309	            format!("{} {}", self.program, command_path.join(" "))
310	        };
311	
312	        let name = command_path
313	            .last()
314	            .map(|s| s.as_str())
315	            .unwrap_or(&self.program);
316	
317	        debug!("Introspecting: {}", full_path);
318	
319	        let help = self.run_help(command_path).await?;
320	
321	        // Parse groups (gcloud-style GROUPS section)
322	        let groups = self.parse_groups(&help);
323	        // Parse commands from all recognized section formats
324	        let commands = self.parse_commands_section(&help);
325	        let flags = self.parse_flags_section(&help);
326	        let description = self.parse_description(&help);
327	
328	        let is_group = !groups.is_empty() || !commands.is_empty();
329	
330	        stats.total_flags += flags.len();
331	        if is_group {
332	            stats.total_groups += 1;
333	        } else {
334	            stats.total_commands += 1;
335	        }
336	
337	        let mut cmd = CliCommand {
338	            name: name.to_string(),
339	            full_path,
340	            description,
341	            is_group,
342	            flags,
343	            positional_args: vec![],
344	            subcommands: HashMap::new(),
345	        };
346	
347	        // Recurse into subcommands if we haven't hit the depth limit
348	        if depth < max_depth {
349	            // Groups are subcommands that themselves contain more commands
350	            for (group_name, _desc) in &groups {
351	                let mut sub_path = command_path.to_vec();
352	                sub_path.push(group_name.clone());
353	
354	                match Box::pin(self.introspect_command_inner(
355	                    &sub_path,
356	                    depth + 1,
357	                    max_depth,
358	                    stats,
359	                ))
360	                .await
361	                {
362	                    Ok(sub_cmd) => {
363	                        cmd.subcommands.insert(group_name.clone(), sub_cmd);
364	                    }
365	                    Err(e) => {
366	                        warn!(
367	                            "Failed to introspect group '{} {}': {}",
368	                            self.program,
369	                            sub_path.join(" "),
370	                            e
371	                        );
372	                    }
373	                }
374	            }
375	
376	            // Leaf commands (may still have further subcommands)
377	            for (cmd_name, _desc) in &commands {
378	                // Avoid duplicates if a name appeared in both GROUPS and COMMANDS
379	                if cmd.subcommands.contains_key(cmd_name) {
380	                    continue;
381	                }
382	
383	                let mut sub_path = command_path.to_vec();
384	                sub_path.push(cmd_name.clone());
385	
386	                match Box::pin(self.introspect_command_inner(
387	                    &sub_path,
388	                    depth + 1,
389	                    max_depth,
390	                    stats,
391	                ))
392	                .await
393	                {
394	                    Ok(sub_cmd) => {
395	                        cmd.subcommands.insert(cmd_name.clone(), sub_cmd);
396	                    }
397	                    Err(e) => {
398	                        warn!(
399	                            "Failed to introspect command '{} {}': {}",
400	                            self.program,
401	                            sub_path.join(" "),
402	                            e
403	                        );
404	                    }
405	                }
406	            }
407	        }
408	
409	        Ok(cmd)
410	    }
411	
412	    // -----------------------------------------------------------------------
413	    // Parsing helpers
414	    // -----------------------------------------------------------------------
415	
416	    /// Parse commands from help output.
417	    ///
418	    /// Recognizes multiple section header styles:
419	    /// - Cobra-style: "Available Commands:", "Additional Commands:"
420	    /// - Click-style: "Commands:"
421	    /// - Gcloud-style: "COMMANDS"
422	    /// - Misc: "Subcommands:", "SUBCOMMANDS"
423	    ///
424	    /// Returns `(name, description)` pairs.
425	    pub fn parse_commands_section(&self, help: &str) -> Vec<(String, String)> {
426	        let mut results = Vec::new();
427	        let mut in_section = false;
428	
429	        let cmd_name_re = Regex::new(r"^\s{2,8}(\w[\w-]*)\s{2,}(.*)$").unwrap();
430	        // Fallback for names with no multi-space gap (single description word)
431	        let cmd_name_simple_re = Regex::new(r"^\s{2,8}(\w[\w-]*)$").unwrap();
432	
433	        for line in help.lines() {
434	            let trimmed = line.trim();
435	
436	            // Detect section headers
437	            if Self::is_commands_header(trimmed) {
438	                in_section = true;
439	                continue;
440	            }
441	
442	            if in_section {
443	                // A non-indented, non-empty line signals end of section
444	                if !line.starts_with(' ') && !trimmed.is_empty() {
445	                    in_section = false;
446	                    continue;
447	                }
448	
449	                // Skip blank lines within the section
450	                if trimmed.is_empty() {
451	                    continue;
452	                }
453	
454	                // Try to extract command name + description
455	                if let Some(caps) = cmd_name_re.captures(line) {
456	                    let name = caps.get(1).unwrap().as_str().to_string();
457	                    let desc = caps.get(2).unwrap().as_str().trim().to_string();
458	                    results.push((name, desc));
459	                } else if let Some(caps) = cmd_name_simple_re.captures(line) {
460	                    let name = caps.get(1).unwrap().as_str().to_string();
461	                    results.push((name, String::new()));
462	                }
463	            }
464	        }
465	
466	        results
467	    }
468	
469	    /// Parse flags from help output.
470	    ///
471	    /// Recognizes section headers:
472	    /// - Cobra-style: "Flags:", "Global Flags:", "Persistent Flags:"
473	    /// - Gcloud-style: "FLAGS", "OPTIONAL FLAGS", "REQUIRED FLAGS", "GLOBAL FLAGS",
474	    ///   "GCLOUD WIDE FLAGS"
475	    /// - Click/argparse-style: "Options:", "Optional arguments:"
476	    ///
477	    /// Handles flag formats:
478	    /// - `--flag-name string   Description text` (cobra)
479	    /// - `-f, --flag-name      Description text` (cobra short+long)
480	    /// - `--flag-name=VALUE    Description text` (gcloud)
481	    /// - `--flag-name          Description text` (boolean flags)
482	    pub fn parse_flags_section(&self, help: &str) -> Vec<CliFlag> {
483	        let mut flags = Vec::new();
484	        let mut in_flags_section = false;
485	        let mut is_required_section = false;
486	        let mut current_flag: Option<CliFlag> = None;
487	
488	        // Pattern: -f, --flag-name value   Description
489	        // Pattern:     --flag-name value    Description
490	        // Pattern:     --flag-name=VALUE    Description
491	        let long_flag_re =
492	            Regex::new(r"^\s+(?:(-\w),\s+)?(--[\w-]+)(?:[=\s]\s*(\w+))?\s{2,}(.*)$").unwrap();
493	        // Simpler: just the flag with no description on this line
494	        let long_flag_simple_re =
495	            Regex::new(r"^\s+(?:(-\w),\s+)?(--[\w-]+)(?:[=\s]\s*(\w+))?\s*$").unwrap();
496	
497	        for line in help.lines() {
498	            let trimmed = line.trim();
499	
500	            // Detect flags section headers
501	            if Self::is_flags_header(trimmed) {
502	                // Flush any pending flag
503	                if let Some(flag) = current_flag.take() {
504	                    flags.push(flag);
505	                }
506	                in_flags_section = true;
507	                is_required_section = trimmed.contains("REQUIRED");
508	                continue;
509	            }
510	
511	            if in_flags_section {
512	                // Non-indented, non-empty line ends the section
513	                if !line.starts_with(' ') && !trimmed.is_empty() && !trimmed.starts_with('-') {
514	                    in_flags_section = false;
515	                    if let Some(flag) = current_flag.take() {
516	                        flags.push(flag);
517	                    }
518	                    continue;
519	                }
520	
521	                // Skip empty lines
522	                if trimmed.is_empty() {
523	                    continue;
524	                }
525	
526	                // Try to match a flag definition line
527	                let matched = if let Some(caps) = long_flag_re.captures(line) {
528	                    Some((
529	                        caps.get(1).map(|m| m.as_str().to_string()),
530	                        caps.get(2).unwrap().as_str().to_string(),
531	                        caps.get(3).map(|m| m.as_str()),
532	                        caps.get(4).map(|m| m.as_str().trim().to_string()),
533	                    ))
534	                } else if let Some(caps) = long_flag_simple_re.captures(line) {
535	                    Some((
536	                        caps.get(1).map(|m| m.as_str().to_string()),
537	                        caps.get(2).unwrap().as_str().to_string(),
538	                        caps.get(3).map(|m| m.as_str()),
539	                        None,
540	                    ))
541	                } else {
542	                    None
543	                };
544	
545	                if let Some((short, long, value_hint, desc)) = matched {
546	                    // Flush previous flag
547	                    if let Some(flag) = current_flag.take() {
548	                        flags.push(flag);
549	                    }
550	
551	                    // Extract default value from description if present
552	                    let (description, default_val) = if let Some(ref d) = desc {
553	                        Self::extract_default(d)
554	                    } else {
555	                        (String::new(), None)
556	                    };
557	
558	                    current_flag = Some(CliFlag {
559	                        name: long,
560	                        short_name: short,
561	                        description,
562	                        required: is_required_section,
563	                        value_type: self.infer_type(value_hint),
564	                        default: default_val,
565	                        choices: vec![],
566	                    });
567	                } else if let Some(ref mut flag) = current_flag {
568	                    // Continuation line for the current flag's description
569	                    if !flag.description.is_empty() {
570	                        flag.description.push(' ');
571	                    }
572	                    flag.description.push_str(trimmed);
573	                }
574	            }
575	        }
576	
577	        // Flush last flag
578	        if let Some(flag) = current_flag {
579	            flags.push(flag);
580	        }
581	
582	        flags
583	    }
584	
585	    /// Parse the description from help output.
586	    ///
587	    /// Looks for "Description:" (title-case) or "DESCRIPTION" (gcloud-style)
588	    /// sections and returns up to the first 3 lines joined with spaces.
589	    /// Falls back to the first non-header, non-empty line if no section found.
590	    pub fn parse_description(&self, help: &str) -> String {
591	        let mut in_description = false;
592	        let mut desc_lines: Vec<String> = Vec::new();
593	
594	        for line in help.lines() {
595	            let trimmed = line.trim();
596	
597	            if trimmed == "DESCRIPTION"
598	                || trimmed == "Description:"
599	                || trimmed.starts_with("DESCRIPTION")
600	            {
601	                in_description = true;
602	                continue;
603	            }
604	
605	            if in_description {
606	                // Non-indented, non-empty → new section
607	                if !line.starts_with(' ') && !trimmed.is_empty() {
608	                    break;
609	                }
610	                if !trimmed.is_empty() {
611	                    desc_lines.push(trimmed.to_string());
612	                }
613	            }
614	        }
615	
616	        desc_lines
617	            .into_iter()
618	            .take(3)
619	            .collect::<Vec<_>>()
620	            .join(" ")
621	    }
622	
623	    /// Parse GROUPS section (gcloud-style).
624	    ///
625	    /// Returns `(name, description)` pairs for each group.
626	    pub fn parse_groups(&self, help: &str) -> Vec<(String, String)> {
627	        let mut groups = Vec::new();
628	        let mut in_groups_section = false;
629	
630	        let name_re = Regex::new(r"^\s{2,8}(\w[\w-]*)\s{2,}(.*)$").unwrap();
631	        let name_simple_re = Regex::new(r"^\s{2,8}(\w[\w-]*)$").unwrap();
632	
633	        for line in help.lines() {
634	            let trimmed = line.trim();
635	
636	            if trimmed == "GROUPS" || trimmed.starts_with("GROUPS") {
637	                in_groups_section = true;
638	                continue;
639	            }
640	
641	            if in_groups_section {
642	                if !line.starts_with(' ') && !trimmed.is_empty() {
643	                    break;
644	                }
645	                if trimmed.is_empty() {
646	                    continue;
647	                }
648	
649	                if let Some(caps) = name_re.captures(line) {
650	                    let name = caps.get(1).unwrap().as_str().to_string();
651	                    let desc = caps.get(2).unwrap().as_str().trim().to_string();
652	                    groups.push((name, desc));
653	                } else if let Some(caps) = name_simple_re.captures(line) {
654	                    let name = caps.get(1).unwrap().as_str().to_string();
655	                    groups.push((name, String::new()));
656	                }
657	            }
658	        }
659	
660	        groups
661	    }
662	
663	    /// Infer the value type from an optional hint string.
664	    ///
665	    /// - "int", "integer", "number" -> "integer"
666	    /// - "bool", "boolean" -> "boolean"
667	    /// - None (no value hint) -> "boolean" (bare flags are typically toggles)
668	    /// - Anything else -> "string"
669	    pub fn infer_type(&self, hint: Option<&str>) -> String {
670	        match hint.map(|s| s.to_lowercase()).as_deref() {
671	            Some("int") | Some("integer") | Some("number") => "integer".to_string(),
672	            Some("bool") | Some("boolean") => "boolean".to_string(),
673	            Some("list") | Some("array") => "array".to_string(),
674	            Some(_) => "string".to_string(),
675	            None => "boolean".to_string(),
676	        }
677	    }
678	
679	    // -----------------------------------------------------------------------
680	    // Private helpers
681	    // -----------------------------------------------------------------------
682	
683	    /// Check if a trimmed line is a commands-section header.
684	    fn is_commands_header(trimmed: &str) -> bool {
685	        trimmed == "COMMANDS"
686	            || trimmed.starts_with("COMMANDS")
687	            || trimmed == "Available Commands:"
688	            || trimmed == "Additional Commands:"
689	            || trimmed == "Commands:"
690	            || trimmed == "Subcommands:"
691	            || trimmed == "SUBCOMMANDS"
692	            || trimmed == "Management Commands:"
693	    }
694	
695	    /// Check if a trimmed line is a flags-section header.
696	    fn is_flags_header(trimmed: &str) -> bool {
697	        trimmed == "Flags:"
698	            || trimmed == "FLAGS"
699	            || trimmed == "Options:"
700	            || trimmed == "Global Flags:"
701	            || trimmed == "Persistent Flags:"
702	            || trimmed.starts_with("OPTIONAL FLAGS")
703	            || trimmed.starts_with("REQUIRED FLAGS")
704	            || trimmed.starts_with("GLOBAL FLAGS")
705	            || trimmed.starts_with("GCLOUD WIDE FLAGS")
706	            || trimmed == "Optional arguments:"
707	    }
708	
709	    /// Extract a default value from a description string.
710	    ///
711	    /// Looks for patterns like `(default "table")` or `(default: 10)`.
712	    fn extract_default(desc: &str) -> (String, Option<String>) {
713	        let default_re =
714	            Regex::new(r#"\(default[:\s]+["']?([^"')]+)["']?\)"#).unwrap();
715	        if let Some(caps) = default_re.captures(desc) {
716	            let default_val = caps.get(1).unwrap().as_str().trim().to_string();
717	            let cleaned = default_re.replace(desc, "").trim().to_string();
718	            (cleaned, Some(default_val))
719	        } else {
720	            (desc.to_string(), None)
721	        }
722	    }
723	}
724	
725	// ---------------------------------------------------------------------------
726	// Convenience function
727	// ---------------------------------------------------------------------------
728	
729	/// Convenience function to introspect any CLI program.
730	///
731	/// Creates a [`CliParser`] with default settings and runs a full introspection
732	/// up to the given depth.
733	pub async fn introspect_cli(program: &str, max_depth: usize) -> Result<CliSchema> {
734	    let parser = CliParser::new(program);
735	    parser.introspect_full(max_depth).await
736	}
