1	//! S6 state plugin — manages services via s6-rc on Artix/Chimera Linux.
2	//!
3	//! AGENTS.md §4 (D-Bus First): This plugin routes ALL control-plane calls
4	//! through the `org.opdbus.v1.S6.Systemctl` D-Bus object instead of spawning
5	//! s6-rc / s6-svc subprocesses directly.  The only exceptions are read-only
6	//! enumeration queries (`s6-rc -a list`) which are considered observations.
7	//!
8	//! OSCAL subids:
9	//!   obs.service.s6.list-units@v1    — query_current_state
10	//!   mut.service.s6.start-unit@v1    — start via D-Bus
11	//!   mut.service.s6.stop-unit@v1     — stop via D-Bus
12	//!   mut.service.s6.restart-unit@v1  — restart via D-Bus
13	//!   mut.service.s6.reload-unit@v1   — reload via D-Bus
14	//!   mut.service.s6.enable-unit@v1   — enable via D-Bus
15	//!   mut.service.s6.disable-unit@v1  — disable via D-Bus
16	
17	use anyhow::{Context, Result};
18	use async_trait::async_trait;
19	use op_state::{
20	    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
21	};
22	use serde::{Deserialize, Serialize};
23	use simd_json::OwnedValue as Value;
24	use std::collections::HashMap;
25	
26	/// Path to the s6-rc live directory.
27	const S6_RC_LIVE: &str = "/run/s6-rc";
28	
29	// ── State structs aligned with schema `units[]` ───────────────────────────────
30	
31	/// Per-service configuration in the desired state.
32	/// Aligned with `s6_plugin_schema()` which declares a `units` **array**.
33	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
34	pub struct S6UnitConfig {
35	    pub name: String,
36	    /// Desired state: "active" or "inactive"
37	    #[serde(skip_serializing_if = "Option::is_none")]
38	    pub state: Option<String>,
39	    /// Whether the unit should be enabled at boot.
40	    #[serde(skip_serializing_if = "Option::is_none")]
41	    pub enabled: Option<bool>,
42	}
43	
44	/// Top-level desired state for the s6 plugin.
45	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
46	pub struct S6Config {
47	    #[serde(skip_serializing_if = "Option::is_none")]
48	    pub units: Option<Vec<S6UnitConfig>>,
49	}
50	
51	/// S6 state plugin — routes mutations through D-Bus, read-only via s6-rc CLI.
52	///
53	/// Automatically resolves systemd-style unit names to s6 primitives at runtime:
54	/// - "nginx.service" → "nginx"
55	/// - "backup.timer"  → s6-cron job
56	/// - "api.socket"    → s6-socketmux
57	///
58	/// Detects actual unit type by inspecting the s6 service directory structure.
59	pub struct S6StatePlugin {
60	    dbus: S6DbusClient,
61	}
62	
63	/// Strip known systemd unit-type suffixes from a name.
64	fn normalize_unit_name(name: &str) -> &str {
65	    for suffix in [
66	        ".service", ".timer", ".socket", ".target", ".mount", ".device", ".path",
67	    ] {
68	        if let Some(base) = name.strip_suffix(suffix) {
69	            return base;
70	        }
71	    }
72	    name
73	}
74	
75	/// Detect the systemd-compatible suffix for a bare s6 service by inspecting
76	/// its service-directory structure under `/run/service/<name>/`.
77	async fn detect_systemd_suffix(name: &str) -> &'static str {
78	    let base = normalize_unit_name(name);
79	    let svc_dir = format!("/run/service/{base}");
80	    let meta = tokio::fs::metadata(&svc_dir).await;
81	    if !meta.as_ref().is_ok_and(|m| m.is_dir()) {
82	        return ".service"; // default assumption
83	    }
84	
85	    // Check for cron subdirectory → timer
86	    if tokio::fs::metadata(format!("{svc_dir}/cron")).await.is_ok() {
87	        return ".timer";
88	    }
89	    // Check for socket subdirectory or s6-socketmux
90	    if tokio::fs::metadata(format!("{svc_dir}/socket"))
91	        .await
92	        .is_ok()
93	        || tokio::fs::metadata(format!("{svc_dir}/env/SOCKET"))
94	            .await
95	            .is_ok()
96	    {
97	        return ".socket";
98	    }
99	    // Check for ftrig / path trigger
100	    if tokio::fs::metadata(format!("{svc_dir}/ftrig"))
101	        .await
102	        .is_ok()
103	        || tokio::fs::metadata(format!("{svc_dir}/env/PATH"))
104	            .await
105	            .is_ok()
106	    {
107	        return ".path";
108	    }
109	    // Check for mount-related env
110	    if tokio::fs::metadata(format!("{svc_dir}/env/MOUNTPOINT"))
111	        .await
112	        .is_ok()
113	    {
114	        return ".mount";
115	    }
116	    ".service"
117	}
118	
119	impl S6StatePlugin {
120	    pub fn new() -> Self {
121	        Self {
122	            dbus: S6DbusClient::new(),
123	        }
124	    }
125	
126	    /// Return the names of all currently-up services (observation path).
127	    ///
128	    /// subid: `obs.service.s6.list-units@v1`
129	    async fn list_running(&self) -> Result<Vec<String>> {
130	        let units = self.dbus.list_units().await?;
131	        let mut running = Vec::new();
132	        for unit in units {
133	            if let Some(name) = unit.get("name").and_then(|v| v.as_str()) {
134	                if let Some(active) = unit.get("active").and_then(|v| v.as_str()) {
135	                    if active == "true" || active == "up" {
136	                        running.push(name.to_string());
137	                    }
138	                }
139	            }
140	        }
141	        Ok(running)
142	    }
143	
144	    /// Return *all* service definitions (available units) via D-Bus.
145	    async fn list_all(&self) -> Result<Vec<String>> {
146	        let files = self.dbus.list_unit_files().await?;
147	        let mut all = Vec::new();
148	        for file in files {
149	            if let Some(name) = file.get("name").and_then(|v| v.as_str()) {
150	                all.push(name.to_string());
151	            }
152	        }
153	        Ok(all)
154	    }
155	
156	    /// Check if a service is enabled by looking at the bundle.
157	    async fn is_enabled(&self, name: &str) -> bool {
158	        let bundle_path = format!("/etc/s6-rc/bundle/default/contents.d/{name}");
159	        tokio::fs::metadata(&bundle_path).await.is_ok()
160	    }
161	}
162	
163	impl Default for S6StatePlugin {
164	    fn default() -> Self {
165	        Self::new()
166	    }
167	}
168	
169	#[async_trait]
170	impl StatePlugin for S6StatePlugin {
171	    fn name(&self) -> &str {
172	        "s6"
173	    }
174	
175	    fn version(&self) -> &str {
176	        "1.0.0"
177	    }
178	
179	    fn schema(&self) -> Option<op_state_store::PluginSchema> {
180	        Some(super::plugin_schema_defs::s6_plugin_schema())
181	    }
182	
183	    fn is_available(&self) -> bool {
184	        std::path::Path::new(S6_RC_LIVE).exists()
185	    }
186	
187	    fn unavailable_reason(&self) -> String {
188	        format!("s6-rc live directory not found at {S6_RC_LIVE}")
189	    }
190	
191	    async fn query_current_state(&self) -> Result<Value> {
192	        let running = self.list_running().await?;
193	        let all = self.list_all().await?;
194	
195	        let mut units = Vec::new();
196	        for name in all {
197	            let is_active = running.contains(&name);
198	            let is_enabled = self.is_enabled(&name).await;
199	            // Auto-detect systemd-compatible suffix from s6 directory structure
200	            let suffix = detect_systemd_suffix(&name).await;
201	            let display_name = format!("{}{}", normalize_unit_name(&name), suffix);
202	            units.push(S6UnitConfig {
203	                name: display_name,
204	                state: Some(if is_active {
205	                    "active".to_string()
206	                } else {
207	                    "inactive".to_string()
208	                }),
209	                enabled: Some(is_enabled),
210	            });
211	        }
212	        Ok(simd_json::serde::to_owned_value(S6Config {
213	            units: Some(units),
214	        })?)
215	    }
216	
217	    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
218	        let current_config: S6Config = simd_json::serde::from_owned_value(current.clone())?;
219	        let desired_config: S6Config = simd_json::serde::from_owned_value(desired.clone())?;
220	        let mut actions = Vec::new();
221	
222	        // Normalize names (strip .service/.timer etc.) so "nginx" and "nginx.service" match
223	        let current_map: std::collections::HashMap<String, S6UnitConfig> = current_config
224	            .units
225	            .unwrap_or_default()
226	            .into_iter()
227	            .map(|u| (normalize_unit_name(&u.name).to_string(), u))
228	            .collect();
229	
230	        if let Some(desired_units) = desired_config.units {
231	            for mut desired in desired_units {
232	                let normalized = normalize_unit_name(&desired.name).to_string();
233	                desired.name = normalized.clone();
234	                let current = current_map.get(&normalized);
235	                if current != Some(&desired) {
236	                    actions.push(StateAction::Modify {
237	                        resource: normalized,
238	                        changes: simd_json::serde::to_owned_value(&desired)?,
239	                    });
240	                }
241	            }
242	        }
243	
244	        Ok(StateDiff {
245	            plugin: self.name().to_string(),
246	            actions,
247	            metadata: DiffMetadata {
248	                timestamp: chrono::Utc::now().timestamp(),
249	                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
250	                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
251	            },
252	        })
253	    }
254	
255	    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
256	        let mut changes_applied = Vec::new();
257	        let mut errors = Vec::new();
258	
259	        for action in &diff.actions {
260	            if let StateAction::Modify { resource, changes } = action {
261	                let unit: S6UnitConfig = simd_json::serde::from_owned_value(changes.clone())?;
262	                // Normalize resource name so "nginx.service" becomes "nginx"
263	                let base = normalize_unit_name(resource).to_string();
264	
265	                // State transition via D-Bus (AGENTS.md §4)
266	                match unit.state.as_deref() {
267	                    Some("active") => {
268	                        if let Err(e) = self.dbus.start(&base).await {
269	                            errors.push(format!("Failed to start {base}: {e}"));
270	                        } else {
271	                            changes_applied.push(format!("Started {base}"));
272	                        }
273	                    }
274	                    Some("inactive") => {
275	                        if let Err(e) = self.dbus.stop(&base).await {
276	                            errors.push(format!("Failed to stop {base}: {e}"));
277	                        } else {
278	                            changes_applied.push(format!("Stopped {base}"));
279	                        }
280	                    }
281	                    _ => {}
282	                }
283	
284	                // Enable / disable via D-Bus (independent of start/stop result)
285	                match unit.enabled {
286	                    Some(true) => {
287	                        if let Err(e) = self.dbus.enable(&base).await {
288	                            errors.push(format!("Failed to enable {base}: {e}"));
289	                        } else {
290	                            changes_applied.push(format!("Enabled {base}"));
291	                        }
292	                    }
293	                    Some(false) => {
294	                        if let Err(e) = self.dbus.disable(&base).await {
295	                            errors.push(format!("Failed to disable {base}: {e}"));
296	                        } else {
297	                            changes_applied.push(format!("Disabled {base}"));
298	                        }
299	                    }
300	                    None => {}
301	                }
302	            }
303	        }
