662	pub fn watch_wireguard_handshakes(iface: &str) {
663	    let iface = iface.to_string();
664	    let poll_secs = std::time::Duration::from_secs(15);
665	    let mut seen: HashSet<String> = HashSet::new();
666	
667	    loop {
668	        std::thread::sleep(poll_secs);
669	
670	        // wg0 lives inside the wg-xray Incus container, not on the host.
671	        let Ok(out) = Command::new("incus")
672	            .args([
673	                "exec",
674	                "wg-xray",
675	                "--",
676	                "wg",
677	                "show",
678	                &iface,
679	                "latest-handshakes",
680	            ])
681	            .output()
682	        else {
683	            continue;
684	        };
685	
686	        if !out.status.success() {
687	            continue;
688	        }
689	
690	        let stdout = String::from_utf8_lossy(&out.stdout);
691	        for line in stdout.lines() {
692	            let mut parts = line.split('\t');
693	            let (Some(pubkey), Some(ts_str)) = (parts.next(), parts.next()) else {
694	                continue;
695	            };
696	            let ts: u64 = ts_str.trim().parse().unwrap_or(0);
697	            if ts == 0 {
698	                continue;
699	            }
700	
701	            // Treat any handshake within the last 3 minutes as "new" if not yet seen
702	            let now = std::time::SystemTime::now()
703	                .duration_since(std::time::UNIX_EPOCH)
704	                .map(|d| d.as_secs())
705	                .unwrap_or(0);
706	            if now.saturating_sub(ts) > 180 {
707	                continue;
708	            }
709	
710	            let key = format!("{}:{}", pubkey, ts);
711	            if seen.contains(&key) {
712	                continue;
713	            }
714	            seen.insert(key);
715	
716	            tracing::info!(peer = %pubkey, "WireGuard handshake → updating identity sled");
717	
718	            if let Err(e) = write_sled_from_wg(pubkey) {
719	                tracing::warn!("write_sled_from_wg failed: {}", e);
720	                continue;
721	            }
722	
723	            // Re-bake xray config — NextDNS profile from env, trace_id from sled.
724	            if let Ok((ptr, _mmap)) = read_sled() {
725	                let sled = unsafe { &*ptr };
726	                let footprint_hex = hex::encode(sled.hashed_footprint);
727	                let trace_id = sled.trace_id_hex();
728	                let Ok(profile) = env::var("NEXTDNS_PROFILE_ID") else {
729	                    tracing::error!("NEXTDNS_PROFILE_ID not set");
730	                    continue;
731	                };
732	                let Ok(uuid) = env::var("XRAY_UUID") else {
733	                    tracing::error!("XRAY_UUID not set");
734	                    continue;
735	                };
736	                let Ok(privkey) = env::var("XRAY_PRIVATE_KEY") else {
