async fn stream_inbox(
    &self,
    _req: Request<StreamInboxRequest>,
) -> Result<Response<Self::StreamInboxStream>, Status> {
    // IMAP IDLE — fires on new messages in INBOX
    let imap_addr = self.imap_addr.clone();
    let stream = async_stream::stream! {
        loop {
            let Ok(stream) = tokio::net::UnixStream::connect(&imap_addr).await else {
                tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;
                continue;
            };
            let user = std::env::var("MAIL_USER").unwrap_or_default();
            let pass = std::env::var("MAIL_PASS").unwrap_or_default();
            let client = async_imap::Client::new(stream);
            let Ok(mut session) = client.login(&user, &pass).await.map_err(|(e, _)| e) else {
                tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;
                continue;
            };
            session.select("INBOX").await.ok();
            let Ok(mut idle) = session.idle().await else { continue };
            loop {
                match idle.wait_with_timeout(std::time::Duration::from_secs(1740)).await {
                    Ok((_, _)) => {
                        yield Ok(MailEvent {
                            event_type: "new_message".to_string(),
                            message: None,
                        });
                    }
                    Err(_) => break,
                }
            }
        }
    };
    Ok(Response::new(Box::pin(stream)))
}

async fn send_message(
    &self,
    req: Request<SendMessageRequest>,
) -> Result<Response<SendMessageResponse>, Status> {
    let r = req.into_inner();
    let from = std::env::var("MAIL_FROM").unwrap_or_default();

    let email = async_smtp::SendableEmail::new(
        async_smtp::Envelope::new(
            Some(async_smtp::EmailAddress::new(from).map_err(|e| Status::invalid_argument(e.to_string()))?),
            vec![async_smtp::EmailAddress::new(r.to).map_err(|e| Status::invalid_argument(e.to_string()))?],
        )
        .map_err(|e| Status::internal(e.to_string()))?,
        uuid::Uuid::new_v4().to_string(),
        format!(
            "Subject: {}\r\nContent-Type: text/plain\r\n\r\n{}",
            r.subject, r.body_text
        )
        .into_bytes(),
    );

    // Connect via unix socket to submission port
    let stream = tokio::net::UnixStream::connect(&self.smtp_addr)
        .await
        .map_err(|e| Status::unavailable(format!("SMTP socket unavailable: {}", e)))?;

    let mut transport = async_smtp::SmtpTransport::new(stream);
    transport
        .send(email)
        .await
        .map_err(|e| Status::internal(format!("SMTP send failed: {}", e)))?;

    Ok(Response::new(SendMessageResponse {
        success: true,
        message_id: uuid::Uuid::new_v4().to_string(),
    }))
}

