1	// dnsresolver_plugin.rs
2	use anyhow::{Context, Result};
3	use async_trait::async_trait;
4	use serde::{Deserialize, Serialize};
5	use simd_json::OwnedValue as Value;
6	use std::fs;
7	
8	use op_state::{
9	    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
10	};
11	use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema};
12	
13	#[derive(Debug, Clone, Serialize, Deserialize)]
14	pub struct DnsState {
15	    pub version: u32,
16	    pub items: Vec<DnsItem>,
17	}
18	
19	#[derive(Debug, Copy, Clone, Serialize, Deserialize)]
20	#[serde(rename_all = "kebab-case")]
21	pub enum Mode {
22	    Enforce,
23	    ObserveOnly,
24	}
25	
26	#[derive(Debug, Clone, Serialize, Deserialize)]
27	pub struct DnsItem {
28	    pub id: String,
29	    pub mode: Mode,
30	    pub servers: Vec<String>,
31	    #[serde(skip_serializing_if = "Option::is_none")]
32	    pub search: Option<Vec<String>>,
33	    #[serde(skip_serializing_if = "Option::is_none")]
34	    pub options: Option<Vec<String>>,
35	}
36	
37	pub struct DnsResolverPlugin;
38	
39	impl Default for DnsResolverPlugin {
40	    fn default() -> Self {
41	        Self
42	    }
43	}
44	
45	impl DnsResolverPlugin {
46	    pub fn new() -> Self {
47	        Self
48	    }
49	
50	    fn parse_resolv_conf(text: &str) -> DnsItem {
51	        let mut servers = Vec::new();
52	        let mut search: Option<Vec<String>> = None;
53	        let mut options: Option<Vec<String>> = None;
54	        for line in text.lines() {
55	            let s = line.trim();
56	            if s.starts_with('#') || s.is_empty() {
57	                continue;
58	            }
59	            let mut parts = s.split_whitespace();
60	            if let Some(keyword) = parts.next() {
61	                match keyword {
62	                    "nameserver" => {
63	                        if let Some(ip) = parts.next() {
64	                            servers.push(ip.to_string());
65	                        }
66	                    }
67	                    "search" => {
68	                        let vals: Vec<String> = parts.map(|v| v.to_string()).collect();
69	                        if !vals.is_empty() {
70	                            search = Some(vals);
71	                        }
72	                    }
73	                    "options" => {
74	                        let vals: Vec<String> = parts.map(|v| v.to_string()).collect();
75	                        if !vals.is_empty() {
76	                            options = Some(vals);
77	                        }
78	                    }
79	                    _ => {}
80	                }
81	            }
82	        }
83	        DnsItem {
84	            id: "resolvconf".into(),
85	            mode: Mode::ObserveOnly,
86	            servers,
87	            search,
88	            options,
89	        }
90	    }
91	
92	    fn read_resolv_conf() -> String {
93	        fs::read_to_string("/etc/resolv.conf").unwrap_or_default()
94	    }
95	
96	    fn write_resolv_conf(item: &DnsItem) -> Result<()> {
97	        let mut buf = String::new();
98	        if let Some(sr) = &item.search {
99	            if !sr.is_empty() {
100	                buf.push_str("search ");
101	                buf.push_str(&sr.join(" "));
102	                buf.push('\n');
103	            }
104	        }
105	        if let Some(opts) = &item.options {
106	            if !opts.is_empty() {
107	                buf.push_str("options ");
108	                buf.push_str(&opts.join(" "));
109	                buf.push('\n');
110	            }
111	        }
112	        for ns in &item.servers {
113	            buf.push_str("nameserver ");
114	            buf.push_str(ns);
115	            buf.push('\n');
